package com.target11.todo.service;import com.target11.todo.config.JwtService;import com.target11.todo.model.AuthenticationRequest;import com.target11.todo.model.AuthenticationResponse;import com.target11.todo.model.RegisterRequest;import com.target11.todo.model.Role;import com.target11.todo.model.User;import com.target11.todo.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;@Service@RequiredArgsConstructorpublic class AuthenticationService {    private final UserRepository repository;    private final PasswordEncoder passwordEncoder;    private final JwtService jwtService;    private final AuthenticationManager authenticationManager;    public AuthenticationResponse register(RegisterRequest request) {        var user = User.builder()                .firstname(request.getFirstname())                .lastname(request.getLastname())                .email(request.getEmail())                .password(passwordEncoder.encode(request.getPassword()))                .role(Role.USER)                .build();        repository.save(user);        var jwtToken = jwtService.generateToken(user);        return AuthenticationResponse.builder()                .token(jwtToken)                .build();    }    public AuthenticationResponse authenticate(AuthenticationRequest request) {        authenticationManager.authenticate(                new UsernamePasswordAuthenticationToken(                        request.getEmail(),                        request.getPassword()                )        );        var user = repository.findByEmail(request.getEmail())                .orElseThrow();        var jwtToken = jwtService.generateToken(user);        return AuthenticationResponse.builder()                .token(jwtToken)                .build();    }}